elements.variants_sample:
HStack(alignment: .top, spacing: 24) {
  VStack(alignment: .leading, spacing: 4) { Button("Label").variant("normal"); Text("normal").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Button("Label").variant("flat"); Text("flat").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Button("Label").variant("highlighted"); Text("highlighted").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Button("Label").variant("default"); Text("default").font(.caption).foregroundStyle(.secondary) }
}

